<?php
namespace App\Services\Football\Tickets;use App\Models\{MarketAnalysis,Ticket};use Carbon\CarbonInterface;final class TicketBuilder{public function build(CarbonInterface $date,array $o=[]):Ticket{$min=(int)($o['minimum_score']??85);$q=(int)($o['minimum_data_quality']??80);$max=(int)($o['maximum_selections']??6);$maxLeague=(int)($o['maximum_per_competition']??2);$markets=$o['allowed_markets']??['team_over_0_5','under_4_5','home','away','team_or_gg'];$query=MarketAnalysis::with(['fixture.competition','fixture.homeTeam','fixture.awayTeam'])->whereHas('fixture',fn($x)=>$x->whereDate('kickoff_at',$date->toDateString()))->whereIn('market_type',$markets)->where('score','>=',$min)->where('data_quality_score','>=',$q)->whereIn('status',['strong_qualified','qualified'])->orderByDesc('score')->orderByDesc('data_quality_score');if((bool)($o['exclude_high_variance']??true))$query->whereHas('fixture.competition',fn($x)=>$x->where('high_variance',false));$chosen=collect();$counts=[];$fixtures=[];foreach($query->get() as$a){if($chosen->count()>=$max)break;$cid=$a->fixture->competition_id;if(($counts[$cid]??0)>=$maxLeague||in_array($a->fixture_id,$fixtures,true))continue;$chosen->push($a);$counts[$cid]=($counts[$cid]??0)+1;$fixtures[]=$a->fixture_id;}$ticket=Ticket::create(['name'=>$o['name']??('Safe shortlist '.$date->format('d M Y')),'fixture_date'=>$date,'minimum_score'=>$min,'minimum_data_quality'=>$q,'maximum_selections'=>$max,'maximum_per_competition'=>$maxLeague,'allowed_markets'=>$markets,'excluded_competition_types'=>['high_variance']]);foreach($chosen->values()as$i=>$a)$ticket->selections()->attach($a->id,['position'=>$i+1]);return$ticket;}}
